<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS debourses (id INT AUTO_INCREMENT PRIMARY KEY,bon_commande_id INT NOT NULL,montant_fournitures DECIMAL(15,2) NOT NULL DEFAULT 0,montant_transport DECIMAL(15,2) NOT NULL DEFAULT 0,statut VARCHAR(30) NOT NULL DEFAULT 'brouillon',valide_le DATETIME NULL,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_debourse_order(bon_commande_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
